import unittest
from candidate import intersperse

class TestIntersperseFunction(unittest.TestCase):
    def test_intersperse_empty_list(self):
        self.assertEqual(intersperse([], 4), [])

    def test_intersperse_single_element_list(self):
        self.assertEqual(intersperse([1], 4), [1])

    def test_intersperse_multiple_elements_list(self):
        self.assertEqual(intersperse([1, 2, 3], 4), [1, 4, 2, 4, 3])

    def test_intersperse_with_zero_delimeter(self):
        self.assertEqual(intersperse([1, 2, 3], 0), [1, 0, 2, 0, 3])

    def test_intersperse_with_negative_delimeter(self):
        self.assertEqual(intersperse([1, 2, 3], -4), [1, -4, 2, -4, 3])

    def test_intersperse_with_none_input(self):
        with self.assertRaises(TypeError):
            intersperse(None, 4)

    def test_intersperse_with_none_delimeter(self):
        with self.assertRaises(TypeError):
            intersperse([1, 2, 3], None)

    def test_intersperse_with_non_list_input(self):
        with self.assertRaises(TypeError):
            intersperse("123", 4)

    def test_intersperse_with_non_int_delimeter(self):
        with self.assertRaises(TypeError):
            intersperse([1, 2, 3], "4")

if __name__ == '__main__':
    unittest.main()
